 181             .interact_opt()?)
 182     }
 183 
 184     fn summary(&mut self, prompt: &str) -> Result<Option<Summary>, CliError> {
 185         let editor = tty::editor_command();
 186         // dialoguer cannot return Esc from a text input, so the prompt names Ctrl-C.
 187         let hint = if editor.is_some() {
 188             format!("{prompt} (leave empty to open $EDITOR; Ctrl-C to cancel)")
 189         } else {
 190             format!("{prompt} (Ctrl-C to cancel)")
 191         };
 192         let opens_editor = editor.is_some();
 193         let line: String = Input::with_theme(&self.theme)
 194             .with_prompt(hint)
 195             .allow_empty(opens_editor)
 196             .validate_with(|line: &String| match Summary::new(line) {
 197                 Err(error) if !(opens_editor && line.is_empty()) => Err(error),
 198                 _ => Ok(()),
 199             })
 200             .interact_text()?;
 201         if let Ok(summary) = Summary::new(&line) {
 202             return Ok(Some(summary));
 203         }
 204         let Some(command) = editor else { return Ok(None) };
 205         Ok(tty::edit(&command)?.and_then(|text| Summary::new(&text).ok()))
 206     }
 207 
 208     fn confirm(&mut self, prompt: &str, default: bool) -> Result<Option<bool>, CliError> {
 209         Ok(Confirm::with_theme(&self.theme)
 210             .with_prompt(prompt)
 211             .default(default)
 212             .interact_opt()?)
 213     }
 214 }
