 368 /// Writes `text` to a new file in `dir` named by `next_slug`, trying another slug whenever the name is taken, including
 369 /// by a changeset another process created after this one looked. Nothing already in `dir` is ever replaced.
 370 fn create_changeset(
 371     dir: &std::path::Path,
 372     archive: &std::path::Path,
 373     text: &str,
 374     permit: &ApplyPermit,
 375     mut next_slug: impl FnMut() -> String,
 376 ) -> Result<String, CliError> {
 377     // 8,000 possible slugs: more than a few attempts only happens when nearly all of them are taken.
 378     for _ in 0..64 {
 379         let filename = format!("{}.md", next_slug());
 380         if archived(archive, &filename)? {
 381             continue;
 382         }
 383         let path = dir.join(&filename);
 384         match callisto_model::atomic::atomic_write_new(&path, text, permit) {
 385             Ok(()) => return Ok(filename),
 386             Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => {}
 387             Err(source) => {
 388                 return Err(CliError::Io {
 389                     source,
 390                     path: Some(path),
 391                 })
 392             }
 393         }
 394     }
 395     Err(CliError::Io {
 396         source: std::io::Error::new(
 397             std::io::ErrorKind::AlreadyExists,
 398             "no unused changeset filename found after 64 attempts",
 399         ),
 400         path: Some(dir.to_path_buf()),
 401     })
 402 }
 403 
 404 /// Whether a Changesets v3 pre cycle archived a note under `filename`; a new note there would read as its duplicate.
 405 fn archived(archive: &std::path::Path, filename: &str) -> Result<bool, CliError> {
 406     let path = archive.join(filename);
 407     callisto_model::strict_fs::exists(&path).map_err(|source| CliError::Io {
 408         source,
 409         path: Some(path),
 410     })
 411 }
 412 
 413 /// Picks a changeset filename that does not exist yet, so a slug collision never overwrites a pending changeset.
 414 fn unused_changeset_filename(dir: &std::path::Path, archive: &std::path::Path) -> Result<String, CliError> {
 415     // 8,000 possible slugs: more than a few attempts only happens when nearly all of them are taken.
 416     for _ in 0..64 {
 417         let filename = format!("{}.md", generate_human_slug());
 418         let path = dir.join(&filename);
 419         let taken = callisto_model::strict_fs::exists(&path).map_err(|source| CliError::Io {
 420             source,
 421             path: Some(path.clone()),
 422         })?;
 423         if !taken && !archived(archive, &filename)? {
 424             return Ok(filename);
 425         }
 426     }
 427     Err(CliError::Io {
 428         source: std::io::Error::new(
 429             std::io::ErrorKind::AlreadyExists,
 430             "no unused changeset filename found after 64 attempts",
 431         ),
 432         path: Some(dir.to_path_buf()),
 433     })
 434 }
 435 
 436 fn generate_human_slug() -> String {
 437     use std::sync::atomic::{AtomicU64, Ordering};
 438 
 439     static COUNTER: AtomicU64 = AtomicU64::new(0);
 440 
 441     let adjectives = [
 442         "swift", "clever", "bright", "silent", "brave", "calm", "eager", "gentle", "happy", "jolly", "keen", "lively",
 443         "mighty", "noble", "proud", "quick", "radiant", "sharp", "tough", "vivid",
 444     ];
 445     let nouns = [
 446         "foxes", "hawks", "wolves", "eagles", "bears", "lions", "otters", "pandas", "falcons", "tigers", "dolphins",
 447         "panthers", "cheetahs", "leopards", "ravens", "badgers", "lynxes", "cobras", "owls", "stags",
 448     ];
 449     let verbs = [
 450         "run", "fly", "leap", "soar", "dash", "hunt", "glide", "climb", "swim", "roar", "pounce", "sprint", "chase",
 451         "race", "bound", "drift", "jump", "strut", "spin", "surge",
 452     ];
 453 
 454     // Each word list has 20 entries; consecutive counter values map to unique triples (a = idx % 20, n = (idx / 20) % 20,
 455     // v = (idx / 400) % 20), a bijection on 0..7999. A timestamp-derived offset varies the start across process restarts.
 456     let ts = std::time::SystemTime::now()
 457         .duration_since(std::time::UNIX_EPOCH)
 458         .map(|d| d.as_nanos() as u64)
 459         .unwrap_or(0);
 460 
 461     let count = COUNTER.fetch_add(1, Ordering::Relaxed);
 462     // Shift ts right to get a slowly-varying cross-run offset (changes every ~1 µs).
 463     let offset = (ts >> 10) % 8000;
 464     let idx = (count + offset) % 8000;
 465 
 466     let a = adjectives[(idx % 20) as usize];
 467     let n = nouns[((idx / 20) % 20) as usize];
 468     let v = verbs[((idx / 400) % 20) as usize];
 469 
 470     format!("{a}-{n}-{v}")
 471 }
