  1	//! The one contract for interactive prompts: where they may run, how Ctrl-C ends them, and how `$EDITOR` is used.
  2	
  3	use std::io::{ErrorKind, IsTerminal as _, Read as _, Write as _};
  4	use std::sync::atomic::{AtomicU8, Ordering};
  5	use std::sync::Once;
  6	
  7	use crate::cli::OutputFormat;
  8	use crate::error::CliError;
  9	use crate::output::prompt_line;
 10	
 11	/// Whether stdin is a terminal; `init` still asks only this.
 12	pub fn is_interactive() -> bool {
 13	    std::io::stdin().is_terminal()
 14	}
 15	
 16	/// Prompts need a person at the terminal (stdin and stderr, where dialoguer draws) and a text run: `--format json` is
 17	/// for scripts and never prompts.
 18	fn may_prompt(format: OutputFormat) -> bool {
 19	    format == OutputFormat::Text && is_interactive() && std::io::stderr().is_terminal()
 20	}
 21	
 22	/// Exit status for Ctrl-C, as shells report SIGINT.
 23	const CANCELLED_BY_SIGINT: i32 = 130;
 24	
 25	/// What owns the terminal when Ctrl-C arrives.
 26	const ELSEWHERE: u8 = 0;
 27	/// A prompt: Ctrl-C cancels the run, and nothing has been written yet.
 28	const PROMPT: u8 = 1;
 29	/// `$EDITOR` shares our process group, so its Ctrl-C reaches us too.
 30	const EDITOR: u8 = 2;
 31	
 32	static AT: AtomicU8 = AtomicU8::new(ELSEWHERE);
 33	
 34	/// Runs `ask` where prompts are allowed, or fails with [`CliError::NotATty`] naming the flags to pass instead.
 35	///
 36	/// Ctrl-C inside `ask`, as a key or a signal, ends the process through [`cancel`]; outside a prompt it exits 130.
 37	pub fn prompting<T>(format: OutputFormat, ask: impl FnOnce() -> Result<T, CliError>) -> Result<T, CliError> {
 38	    if !may_prompt(format) {
 39	        return Err(CliError::NotATty);
 40	    }
 41	    terminal::save();
 42	    // Without the handler SIGINT kills the process with the cursor hidden, so a failure to install it is not fatal.
 43	    drop(ctrlc::set_handler(|| match AT.load(Ordering::SeqCst) {
 44	        PROMPT => cancel(),
 45	        EDITOR => {}
 46	        _ => std::process::exit(CANCELLED_BY_SIGINT),
 47	    }));
 48	    AT.store(PROMPT, Ordering::SeqCst);
 49	    let result = ask();
 50	    if matches!(&result, Err(CliError::Interactive(dialoguer::Error::IO(error))) if error.kind() == ErrorKind::Interrupted)
 51	    {
 52	        cancel();
 53	    }
 54	    AT.store(ELSEWHERE, Ordering::SeqCst);
 55	    result
 56	}
 57	
 58	static CLEANUP: Once = Once::new();
 59	
 60	/// Restores the terminal and cursor, says nothing was written and exits 130. The signal handler and the prompt may
 61	/// both get here; the cleanup runs once and the later caller waits for it to finish before exiting.
 62	fn cancel() -> ! {
 63	    CLEANUP.call_once(|| {
 64	        terminal::restore();
 65	        drop(dialoguer::console::Term::stderr().show_cursor());
 66	        prompt_line(CANCELLED);
 67	    });
 68	    std::process::exit(CANCELLED_BY_SIGINT)
 69	}
 70	
 71	/// The terminal settings from before the first prompt; a prompt killed mid-read leaves the terminal raw.
 72	#[cfg(unix)]
 73	mod terminal {
 74	    use std::sync::OnceLock;
 75	
 76	    use rustix::termios::{tcgetattr, tcsetattr, OptionalActions, Termios};
 77	
 78	    static SAVED: OnceLock<Termios> = OnceLock::new();
 79	
 80	    pub fn save() {
 81	        if let Ok(settings) = tcgetattr(std::io::stdin()) {
 82	            drop(SAVED.set(settings));
 83	        }
 84	    }
 85	
 86	    pub fn restore() {
 87	        if let Some(settings) = SAVED.get() {
 88	            // Best effort: the process is exiting and has nowhere to report a failure.
 89	            tcsetattr(std::io::stdin(), OptionalActions::Now, settings).ok();
 90	        }
 91	    }
 92	}
 93	
 94	#[cfg(not(unix))]
 95	mod terminal {
 96	    pub fn save() {}
 97	    pub fn restore() {}
 98	}
 99	
100	/// Printed whenever a prompt run ends without writing.
101	pub const CANCELLED: &str = "Cancelled, nothing written.";
102	
103	/// The editor from `$VISUAL`, else `$EDITOR`; an empty or blank setting is unset.
104	pub fn editor_command() -> Option<String> {
105	    ["VISUAL", "EDITOR"]
106	        .into_iter()
107	        .filter_map(|name| std::env::var(name).ok())
108	        .find(|command| !command.trim().is_empty())
109	}
110	
111	/// Opens `command` on an empty file and returns what was saved. `None` when the editor exits non-zero (an abort, as
112	/// `:cq` in Vim). The editor draws on stderr so stdout stays for the report.
113	pub fn edit(command: &str) -> Result<Option<String>, CliError> {
114	    let mut file = tempfile::Builder::new().prefix("callisto-").suffix(".txt").tempfile()?;
115	    file.flush()?;
116	    let mut words = shell_words::split(command).unwrap_or_else(|_| vec![command.to_owned()]);
117	    if words.is_empty() {
118	        return Ok(None);
119	    }
120	    let program = words.remove(0);
121	    let before = AT.swap(EDITOR, Ordering::SeqCst);
122	    let status = crate::runner::child_command(&program, &[], &[])
123	        .args(words)
124	        .arg(file.path())
125	        .stdout(std::io::stderr())
126	        .status();
127	    AT.store(before, Ordering::SeqCst);
128	    if !status?.success() {
129	        return Ok(None);
130	    }
131	    let mut written = String::new();
132	    std::fs::File::open(file.path())?.read_to_string(&mut written)?;
133	    Ok(Some(written))
134	}
