   1 use std::collections::{BTreeMap, BTreeSet};
   2 use std::path::{Path, PathBuf};
   3 
   4 use callisto_model::vcs::{GitAccess, GitStdout, VcsError};
   5 use callisto_model::{Package, PackageId};
   6 use globset::{GlobBuilder, GlobSet, GlobSetBuilder};
   7 
   8 use crate::config::GroupTable;
   9 use crate::error::GraphError;
  10 use crate::tags::TagIndex;
  11 
  12 pub fn package_paths(pkg: &Package) -> Vec<PathBuf> {
  13     let mut set = std::collections::BTreeSet::new();
  14     for m in &pkg.manifests {
  15         if let Some(parent) = m.path.parent() {
  16             if parent.as_os_str().is_empty() {
  17                 set.insert(PathBuf::from("."));
  18             } else {
  19                 set.insert(parent.to_path_buf());
  20             }
  21         }
  22     }
  23     set.into_iter().collect()
  24 }
  25 
  26 /// What changed between where a ref and `HEAD` diverged and the working tree.
  27 #[derive(Clone, Debug, Default, PartialEq, Eq)]
  28 pub struct ChangedSince {
  29     /// Packages with a changed file outside the changesets directory; a file belongs to the package whose directory
  30     /// holds it most closely.
  31     pub packages: BTreeSet<PackageId>,
  32     /// Ids of the changesets changed in that span, the only ones that can account for those packages.
  33     pub changesets: BTreeSet<String>,
  34 }
  35 
  36 /// [`ChangedSince`] for `since`, untracked files included. Three git processes, however many packages there are.
  37 pub fn changed_since_ref(
  38     packages: &[&Package],
  39     git: &GitAccess<'_>,
  40     since: &str,
  41     changesets_dir: &Path,
  42 ) -> Result<ChangedSince, GraphError> {
  43     let target = format!("{since}^{{commit}}");
  44     let output = git
  45         .runner()
  46         .run("git", &["merge-base", &target, "HEAD"], git.root())
  47         .map_err(VcsError::from)?;
  48     let Ok(base) = GitStdout::of(output) else {
  49         return Err(GraphError::Vcs(VcsError::RefNotFound {
  50             ref_name: since.to_string(),
  51         }));
  52     };
  53     let mut paths = git.paths_differing_from(base.line())?;
  54     paths.extend(git.untracked_paths()?);
  55 
  56     let dirs: Vec<(PathBuf, &PackageId)> = packages
  57         .iter()
  58         .flat_map(|pkg| package_paths(pkg).into_iter().map(move |dir| (dir, &pkg.id)))
  59         .map(|(dir, id)| (if dir == Path::new(".") { PathBuf::new() } else { dir }, id))
  60         .collect();
  61     let mut changed = ChangedSince::default();
  62     for path in &paths {
  63         if let Ok(inside) = path.strip_prefix(changesets_dir) {
  64             // Only a direct child is a changeset the loader reads.
  65             if inside.components().count() == 1
  66                 && inside.extension().is_some_and(|ext| ext == "md")
  67                 && let Some(id) = inside.file_stem().and_then(|stem| stem.to_str())
  68             {
  69                 changed.changesets.insert(id.to_owned());
  70             }
  71             continue;
  72         }
  73         let owner = dirs
  74             .iter()
  75             .filter(|(dir, _)| path.starts_with(dir))
  76             .max_by_key(|(dir, _)| dir.components().count());
  77         if let Some((_, id)) = owner {
  78             changed.packages.insert((*id).clone());
  79         }
  80     }
  81     Ok(changed)
  82 }
