  89 /// grow with the number of commits. Uncommitted changes come from one `git diff`.
  90 pub fn changed_since_last_tag(
  91     packages: &[&Package],
  92     tags: &TagIndex,
  93     git: &GitAccess<'_>,
  94 ) -> Result<BTreeMap<PackageId, bool>, GraphError> {
