  96     let mut tagged = Vec::new();
  97     for pkg in packages {
  98         match tags.last_tag(&pkg.id) {
  99             Some(last) => tagged.push((*pkg, last.name.as_str())),
 100             None => {
 101                 changed.insert(pkg.id.clone(), true);
 102             }
 103         }
 104     }
 105     if tagged.is_empty() {
 106         return Ok(changed);
 107     }
 108 
 109     let specs: Vec<Vec<PathBuf>> = tagged.iter().map(|(pkg, _)| package_paths(pkg)).collect();
 110     let mut differs = vec![false; tagged.len()];
 111     // Each package directory is asked for twice, at its tag and at `HEAD`; `pair_owners` says whose pair it is.
 112     let mut objects = Vec::new();
 113     let mut pair_owners = Vec::new();
 114     for (index, ((_, tag), directories)) in tagged.iter().zip(&specs).enumerate() {
 115         let Some(commit) = tags.commit_of(git, tag)? else {
 116             // A tag that does not end at a commit cannot be compared, so the package is proposed for release.
 117             differs[index] = true;
 118             continue;
 119         };
 120         for directory in directories {
 121             // `./` anchors the path at the working directory; a bare `rev:path` resolves from the repository top.
 122             let directory = if directory.as_path() == Path::new(".") {
 123                 "./".to_owned()
 124             } else {
 125                 format!("./{}", directory.to_string_lossy())
 126             };
 127             objects.push(format!("{}:{directory}", commit.as_str()));
 128             objects.push(format!("HEAD:{directory}"));
 129             pair_owners.push(index);
 130         }
 131     }
 132     let ids = git.object_ids(&objects)?;
 133     for (pair, &owner) in pair_owners.iter().enumerate() {
 134         if ids[2 * pair] != ids[2 * pair + 1] {
 135             differs[owner] = true;
 136         }
 137     }
 138 
 139     // Uncommitted changes count for every package they touch; a diff that could not run counts as changed.
 140     let uncommitted = match git.paths_differing_from("HEAD") {
 141         Ok(paths) => Some(paths),
 142         Err(VcsError::Command(e)) => return Err(VcsError::Command(e).into()),
 143         Err(_) => None,
 144     };
 145     let owners = SpecIndex::new(&specs);
 146     let mut dirty = vec![uncommitted.is_none(); tagged.len()];
 147     for path in uncommitted.iter().flatten() {
 148         owners.owners_of(path, |package| dirty[package] = true);
 149     }
 150     for (index, (pkg, _)) in tagged.iter().enumerate() {
 151         changed.insert(pkg.id.clone(), differs[index] || dirty[index]);
 152     }
