  38     packages: &[&Package],
  39     git: &GitAccess<'_>,
  40     since: &str,
  41     changesets_dir: &Path,
  42 ) -> Result<ChangedSince, GraphError> {
  43     let target = format!("{since}^{{commit}}");
  44     let output = git
  45         .runner()
  46         .run("git", &["merge-base", &target, "HEAD"], git.root())
  47         .map_err(VcsError::from)?;
  48     let Ok(base) = GitStdout::of(output) else {
  49         return Err(GraphError::Vcs(VcsError::RefNotFound {
  50             ref_name: since.to_string(),
  51         }));
  52     };
  53     let mut paths = git.paths_differing_from(base.line())?;
  54     paths.extend(git.untracked_paths()?);
  55 
  56     let dirs: Vec<(PathBuf, &PackageId)> = packages
  57         .iter()
  58         .flat_map(|pkg| package_paths(pkg).into_iter().map(move |dir| (dir, &pkg.id)))
  59         .map(|(dir, id)| (if dir == Path::new(".") { PathBuf::new() } else { dir }, id))
  60         .collect();
  61     let mut changed = ChangedSince::default();
  62     for path in &paths {
  63         if let Ok(inside) = path.strip_prefix(changesets_dir) {
  64             // Only a direct child is a changeset the loader reads.
  65             if inside.components().count() == 1
  66                 && inside.extension().is_some_and(|ext| ext == "md")
