  1 //! `callisto add`'s wizard driven through a real pseudo-terminal: keys in, rendered output and exit status out.
  2 #![cfg(unix)]
  3 
  4 use std::io::{Read, Write};
  5 use std::path::Path;
  6 use std::process::{Child, Command, Stdio};
  7 use std::sync::{Arc, Mutex};
  8 use std::time::{Duration, Instant};
  9 
 10 use callisto_fixtures::git::{init_repo, run_git};
 11 use rustix::pty::{grantpt, openpt, ptsname, unlockpt, OpenptFlags};
 12 
 13 const HIDE_CURSOR: &str = "\x1b[?25l";
 14 const SHOW_CURSOR: &str = "\x1b[?25h";
 15 
 16 /// npm packages `a` and `b`, both released at 1.0.0, then `b` changed.
 17 fn workspace() -> tempfile::TempDir {
 18     let dir = tempfile::tempdir().unwrap();
 19     let root = dir.path();
 20     init_repo(root);
 21     std::fs::write(
 22         root.join("package.json"),
 23         r#"{"name":"root","private":true,"workspaces":["packages/*"]}"#,
 24     )
 25     .unwrap();
 26     for name in ["a", "b"] {
 27         std::fs::create_dir_all(root.join(format!("packages/{name}"))).unwrap();
 28         std::fs::write(
 29             root.join(format!("packages/{name}/package.json")),
 30             format!(r#"{{"name":"{name}","version":"1.0.0"}}"#),
 31         )
 32         .unwrap();
 33     }
 34     std::fs::write(root.join("callisto.toml"), "").unwrap();
 35     run_git(root, &["add", "-A"]);
 36     run_git(root, &["commit", "-qm", "release"]);
 37     run_git(root, &["tag", "a@1.0.0"]);
 38     run_git(root, &["tag", "b@1.0.0"]);
 39     std::fs::write(root.join("packages/b/index.js"), "x").unwrap();
 40     run_git(root, &["add", "-A"]);
 41     run_git(root, &["commit", "-qm", "change b"]);
 42     dir
 43 }
 44 
 45 /// `callisto add` on a pty: the child, the master side to type into, and everything it has printed so far.
 46 struct Session {
 47     child: Child,
 48     master: std::fs::File,
 49     /// The child's terminal, kept open to read its settings after the child exits.
 50     tty: std::fs::File,
 51     screen: Arc<Mutex<String>>,
 52 }
 53 
 54 impl Session {
 55     fn start(root: &Path) -> Self {
 56         Self::start_with(root, &["add"], &[])
 57     }
 58 
 59     /// `callisto <args>` with `env` set; `VISUAL` and `EDITOR` are unset unless `env` names them.
 60     fn start_with(root: &Path, args: &[&str], env: &[(&str, &str)]) -> Self {
 61         let master = openpt(OpenptFlags::RDWR | OpenptFlags::NOCTTY).unwrap();
 62         grantpt(&master).unwrap();
 63         unlockpt(&master).unwrap();
 64         let name = ptsname(&master, Vec::new()).unwrap();
 65         let tty = std::fs::OpenOptions::new()
 66             .read(true)
 67             .write(true)
 68             .open(name.to_str().unwrap())
 69             .unwrap();
 70         rustix::termios::tcsetwinsize(
 71             &tty,
 72             rustix::termios::Winsize {
 73                 ws_row: 30,
 74                 ws_col: 120,
 75                 ws_xpixel: 0,
 76                 ws_ypixel: 0,
 77             },
 78         )
 79         .unwrap();
 80         let child = Command::new(env!("CARGO_BIN_EXE_callisto"))
 81             .args(["--cwd", root.to_str().unwrap()])
 82             .args(args)
 83             .env_remove("VISUAL")
 84             .env_remove("EDITOR")
 85             .envs(env.iter().copied())
 86             .env("TERM", "xterm-256color")
 87             .stdin(Stdio::from(tty.try_clone().unwrap()))
 88             .stdout(Stdio::from(tty.try_clone().unwrap()))
 89             .stderr(Stdio::from(tty.try_clone().unwrap()))
 90             .spawn()
 91             .unwrap();
 92         let master = std::fs::File::from(master);
 93         let screen = Arc::new(Mutex::new(String::new()));
 94         let mut reader = master.try_clone().unwrap();
 95         let sink = Arc::clone(&screen);
 96         std::thread::spawn(move || {
 97             let mut buf = [0u8; 4096];
 98             // The read fails with EIO once the child has exited and closed the terminal.
 99             while let Ok(n @ 1..) = reader.read(&mut buf) {
100                 sink.lock().unwrap().push_str(&String::from_utf8_lossy(&buf[..n]));
101             }
102         });
103         Session {
104             child,
105             master,
106             tty,
107             screen,
108         }
109     }
110 
111     fn screen(&self) -> String {
112         self.screen.lock().unwrap().clone()
113     }
114 
115     /// Waits until the output contains `text` `times` times, then types `keys`.
116     fn after(&mut self, text: &str, times: usize, keys: &str) {
117         let deadline = Instant::now() + Duration::from_secs(20);
118         while self.screen().matches(text).count() < times {
119             assert!(Instant::now() < deadline, "never saw {text:?}:\n{}", self.screen());
120             std::thread::sleep(Duration::from_millis(20));
121         }
122         // Let the prompt finish drawing and switch the terminal to raw mode before typing.
123         std::thread::sleep(Duration::from_millis(200));
124         self.master.write_all(keys.as_bytes()).unwrap();
125     }
126 
127     /// Delivers SIGINT to the child itself, as `kill -INT` or a closing terminal would, with no Ctrl-C byte typed.
128     fn interrupt(&self) {
129         let status = Command::new("kill")
130             .args(["-INT", &self.child.id().to_string()])
131             .status()
132             .unwrap();
133         assert!(status.success());
134     }
135 
136     /// The terminal is back in line mode with echo, as the shell expects after the child exits.
137     fn assert_terminal_restored(&self) {
138         let out = Command::new("stty")
139             .arg("-a")
140             .stdin(self.tty.try_clone().unwrap())
141             .output()
142             .unwrap();
143         let settings = String::from_utf8_lossy(&out.stdout);
144         let flags: Vec<&str> = settings.split(|c: char| c.is_whitespace() || c == ';').collect();
145         assert!(
146             flags.contains(&"icanon") && flags.contains(&"echo"),
147             "the terminal is left raw:\n{settings}"
148         );
149     }
150 
151     fn exit_code(&mut self) -> Option<i32> {
152         let deadline = Instant::now() + Duration::from_secs(20);
153         loop {
154             if let Some(status) = self.child.try_wait().unwrap() {
155                 std::thread::sleep(Duration::from_millis(200));
156                 return status.code();
157             }
158             assert!(Instant::now() < deadline, "add did not exit:\n{}", self.screen());
159             std::thread::sleep(Duration::from_millis(20));
160         }
161     }
162 }
163 
164 fn changesets(root: &Path) -> Vec<String> {
165     std::fs::read_dir(root.join(".changeset"))
166         .map(|entries| {
167             entries
168                 .map(|e| e.unwrap().path())
169                 .filter(|path| path.extension().is_some_and(|ext| ext == "md"))
170                 .filter(|path| path.file_name().is_some_and(|name| name != "README.md"))
171                 .map(|path| std::fs::read_to_string(path).unwrap())
172                 .collect()
173         })
174         .unwrap_or_default()
175 }
176 
177 #[test]
178 fn the_changed_package_is_ticked_so_enter_through_the_wizard_records_it() {
179     let dir = workspace();
180     let mut add = Session::start(dir.path());
181     add.after("Packages in this change", 1, "\r");
182     add.after("MAJOR", 1, "\r");
183     add.after("MINOR", 1, "\r");
184     add.after("Changelog summary", 1, "Fix b\r");
185     add.after("Write this changeset?", 1, "\r");
186     assert_eq!(add.exit_code(), Some(0), "{}", add.screen());
187     let screen = add.screen();
188     assert!(screen.contains("b (changed)"), "{screen}");
189     assert!(screen.contains("patch  b"), "the review lists the bump:\n{screen}");
190     assert!(screen.contains("Next:"), "{screen}");
191     assert_eq!(changesets(dir.path()), ["---\nb: patch\n---\n\nFix b\n"]);
192 }
193 
194 #[test]
195 fn ctrl_c_at_a_prompt_restores_the_cursor_writes_nothing_and_exits_130() {
196     let dir = workspace();
197     let mut add = Session::start(dir.path());
198     add.after("Packages in this change", 1, "\x03");
199     assert_eq!(add.exit_code(), Some(130), "{}", add.screen());
200     let screen = add.screen();
201     assert!(screen.contains("Cancelled, nothing written."), "{screen}");
202     assert!(
203         screen.rfind(SHOW_CURSOR) > screen.rfind(HIDE_CURSOR),
204         "the cursor is left hidden:\n{screen:?}"
205     );
206     add.assert_terminal_restored();
207     assert!(changesets(dir.path()).is_empty());
208 }
