210 #[test]
211 fn esc_at_a_prompt_writes_nothing_and_exits_0() {
212     let dir = workspace();
213     let mut add = Session::start(dir.path());
214     add.after("Packages in this change", 1, "\r");
215     add.after("MAJOR", 1, "\x1b");
216     assert_eq!(add.exit_code(), Some(0), "{}", add.screen());
