151     fn exit_code(&mut self) -> Option<i32> {
152         let deadline = Instant::now() + Duration::from_secs(20);
153         loop {
154             if let Some(status) = self.child.try_wait().unwrap() {
155                 std::thread::sleep(Duration::from_millis(200));
156                 return status.code();
157             }
158             assert!(Instant::now() < deadline, "add did not exit:\n{}", self.screen());
159             std::thread::sleep(Duration::from_millis(20));
160         }
161     }
